s_spls_rgr_b		="A partir do 4º nível, patrulheiras podem conjurar um pequeno número de magias divinas com Sabedoria."
s_spls_rgr_d		=[[A partir do 4º nível, uma patrulheira ganha a habilidade de conjurar um pequeno número de magias divinas. As magias disponíveis serão aprendidas automaticamente ao subir de nível. Uma patrulheira deve escolher e preparar suas magias com antecedência.

